 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    axes = []

    # Each solid 3x3 colored object projects its central row and column.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                axes.append((r + 1, c + 1, color))

    claims = {}
    for row, col, color in axes:
        for cc in range(w):
            claims.setdefault((row, cc), set()).add(color)
        for rr in range(h):
            claims.setdefault((rr, col), set()).add(color)

    for (r, c), colors in claims.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
